import{_ as c,r as t,o as l,c as i,e,a as s,d as a,s as r}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"模型 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"定义模型","slug":"定义模型","link":"#定义模型","children":[{"level":3,"title":"支持的属性","slug":"支持的属性","link":"#支持的属性","children":[{"level":4,"title":"主键","slug":"主键","link":"#主键","children":[]},{"level":4,"title":"递增","slug":"递增","link":"#递增","children":[]},{"level":4,"title":"时间戳","slug":"时间戳","link":"#时间戳","children":[]},{"level":4,"title":"值存储为 JSON","slug":"值存储为-json","link":"#值存储为-json","children":[]}]}]},{"level":2,"title":"检索模型","slug":"检索模型","link":"#检索模型","children":[{"level":3,"title":"检索多个模型","slug":"检索多个模型","link":"#检索多个模型","children":[{"level":4,"title":"访问字段值","slug":"访问字段值","link":"#访问字段值","children":[]},{"level":4,"title":"添加额外的约束","slug":"添加额外的约束","link":"#添加额外的约束","children":[]},{"level":4,"title":"集合","slug":"集合","link":"#集合","children":[]},{"level":4,"title":"分块结果","slug":"分块结果","link":"#分块结果","children":[]}]},{"level":3,"title":"检索单个模型","slug":"检索单个模型","link":"#检索单个模型","children":[{"level":4,"title":"\\"未找到\\"异常","slug":"未找到-异常","link":"#未找到-异常","children":[]}]},{"level":3,"title":"检索集合","slug":"检索集合","link":"#检索集合","children":[]}]},{"level":2,"title":"插入 & 更新模型","slug":"插入-更新模型","link":"#插入-更新模型","children":[{"level":3,"title":"插入","slug":"插入","link":"#插入","children":[]},{"level":3,"title":"更新","slug":"更新","link":"#更新","children":[]},{"level":3,"title":"批量赋值","slug":"批量赋值","link":"#批量赋值","children":[{"level":4,"title":"其他创建方式","slug":"其他创建方式","link":"#其他创建方式","children":[]}]}]},{"level":2,"title":"删除模型","slug":"删除模型","link":"#删除模型","children":[{"level":4,"title":"通过主键删除模型","slug":"通过主键删除模型","link":"#通过主键删除模型","children":[]},{"level":4,"title":"通过查询删除模型","slug":"通过查询删除模型","link":"#通过查询删除模型","children":[]}]},{"level":2,"title":"查询范围","slug":"查询范围","link":"#查询范围","children":[{"level":4,"title":"使用查询范围","slug":"使用查询范围","link":"#使用查询范围","children":[]},{"level":4,"title":"动态范围","slug":"动态范围","link":"#动态范围","children":[]}]},{"level":2,"title":"事件","slug":"事件","link":"#事件","children":[{"level":3,"title":"基本用法","slug":"基本用法","link":"#基本用法","children":[]}]},{"level":2,"title":"扩展模型","slug":"扩展模型","link":"#扩展模型","children":[]}],"relativePath":"2.x/zh-cn/database/model.md","filePath":"2.x/zh-cn/database/model.md"}'),u={name:"2.x/zh-cn/database/model.md"};function k(d,n,g,h,f,m){const p=t("pre-heading"),o=t("post-heading");return l(),i("div",null,[e(p),n[0]||(n[0]=s("h1",null,"模型",-1)),e(o),n[1]||(n[1]=s("p",null,[a("October CMS 基于 "),s("a",{href:"http://laravel.com/docs/eloquent",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Laravel 的 Eloquent"),s("span",null,[s("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[s("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),s("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),s("span",{class:"sr-only"},"(opens new window)")])]),a(' 提供了一个漂亮而简单的 Active Record 实现来处理您的数据库。 每个数据库表都有一个相应的"Model"，用于与该表进行交互。 模型允许您查询表中的数据，以及将新记录插入表中。')],-1)),n[2]||(n[2]=r(`<p>模型类位于插件目录的 <strong>models</strong> 子目录中。 模型目录结构示例：</p><div class="language- extra-class"><pre class="language-text"><code>plugins/
  acme/
    blog/
      models/
      user/             &lt;=== 配置目录
        columns.yaml    &lt;=== 配置文件
        fields.yaml     &lt;==^
      User.php          &lt;=== 模型类
      Plugin.php
</code></pre></div><p>模型配置目录可以包含模型的 <a href="./../backend/lists.html#oc-defining-list-columns">列表字段</a> 和 <a href="./../backend/forms.html#oc-defining-form-fields">form field</a> 定义 . 模型配置目录名与小写的模型类名一致。</p><h2 id="定义模型"><a href="#定义模型" class="header-anchor">#</a> 定义模型</h2><p>在大多数情况下，您应该为每个数据库表创建一个模型类。 所有模型类都必须扩展<code>Model</code>类。 插件中使用的模型的最基本表示如下所示：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">namespace</span> <span class="token package">Acme<span class="token punctuation">\\</span>Blog<span class="token punctuation">\\</span>Models</span><span class="token punctuation">;</span>

<span class="token keyword">use</span> <span class="token package">Model</span><span class="token punctuation">;</span>

<span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 与模型关联的表。
     *
     * @var string
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$table</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;acme_blog_posts&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>protected<code>$table</code>字段指定模型对应的数据库表。 表名是作者、插件和记录类型名称的蛇形命名名称。</p><p><a id="oc-supported-properties"></a></p><h3 id="支持的属性"><a href="#支持的属性" class="header-anchor">#</a> 支持的属性</h3><p>除了 <a href="./traits.html">模型特征</a> 提供的那些之外，还可以在模型上找到一些标准属性。 例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$exists</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$dates</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;last_seen_at&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">true</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;permissions&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

    <span class="token keyword">protected</span> <span class="token variable">$guarded</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>$primaryKey</strong></td><td>用于标识模型的主键名称。</td></tr><tr><td><strong>$incrementing</strong></td><td>布尔值，如果 false 表示主键不是递增的整数值。</td></tr><tr><td><strong>$exists</strong></td><td>布尔值，如果为 true，则表示模型存在。</td></tr><tr><td><strong>$dates</strong></td><td>获取后，值将转换为 Carbon/DateTime 对象的实例。</td></tr><tr><td><strong>$timestamps</strong></td><td>布尔值，如果为 true 将自动设置 created_at 和 updated_at 字段。</td></tr><tr><td><strong>$jsonable</strong></td><td>值在保存之前被编码为 JSON，并在获取后转换为数组。</td></tr><tr><td><strong>$fillable</strong></td><td>values 是 <a href="#oc-mass-assignment">批量赋值</a> 可访问的字段。</td></tr><tr><td><strong>$guarded</strong></td><td>值是受 <a href="#oc-mass-assignment">批量赋值</a> 保护的字段。</td></tr><tr><td><strong>$visible</strong></td><td>值是在 <a href="./../database/serialization.html">序列化模型数据</a> 时可见的字段。</td></tr><tr><td><strong>$hidden</strong></td><td>值是在 <a href="./../database/serialization.html">序列化模型数据</a> 时隐藏的字段。</td></tr><tr><td><strong>$connection</strong></td><td>包含模型默认使用的 <a href="./../database/basics.html#oc-multiple-database-connections">连接名称</a> 的字符串。</td></tr></tbody></table></div><h4 id="主键"><a href="#主键" class="header-anchor">#</a> 主键</h4><p>Eloquent 也会假设每个数据表都有一个名为 <code>id</code> 的主键列。你可以定义一个受保护的 <code>$primaryKey</code> 属性来重写约定。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 模型的主键
     *
     * @var string
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$primaryKey</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;id&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="递增"><a href="#递增" class="header-anchor">#</a> 递增</h4><p>模型将假设主键是一个自增的整数值，这意味着默认情况下主键将自动转换为整数。如果您希望使用非递增或非数字主键，则必须将 public <code>$incrementing</code>属性设置为 false</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Message</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 模型的主键不是整数。
     *
     * @var bool
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$incrementing</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="时间戳"><a href="#时间戳" class="header-anchor">#</a> 时间戳</h4><p>默认情况下，模型期望你的数据表中存在 <code>created_at</code> 和 <code>updated_at</code> 。如果你不想让模型自动管理这两个字段， 请将模型中的 <code>$timestamps</code> 属性设置为 <code>false</code>：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 指示模型是否应加时间戳。
     *
     * @var bool
     */</span>
    <span class="token keyword">public</span> <span class="token variable">$timestamps</span> <span class="token operator">=</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>如果您需要自定义时间戳的格式，请在模型上设置 <code>$dateFormat</code> 属性。此属性确定日期属性在数据库中的存储方式，以及模型序列化为数组或 JSON 时的格式：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 模型日期字段的存储格式。
     *
     * @var string
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$dateFormat</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;U&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="值存储为-json"><a href="#值存储为-json" class="header-anchor">#</a> 值存储为 JSON</h4><p>当属性名称被传递给 <code>$jsonable</code> 属性时，这些值将作为 JSON 从数据库中序列化和反序列化：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Post</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * @var array 使用 JSON 编码和解码的属性名称。
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$jsonable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;data&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="检索模型"><a href="#检索模型" class="header-anchor">#</a> 检索模型</h2><p>当从数据库请求数据时，模型将主要使用 <code>get</code> 或 <code>first</code> 方法检索值，具体取决于您是希望 <a href="#oc-retrieving-multiple-models">检索多个模型</a> 还是 <a href="#oc-retrieving-a-single-model">检索单个模型</a>。从模型派生的查询返回 <a href="./../api/october/rain/database/builder.html">October\\Rain\\Database\\Builder</a> 的实例。</p><p><a id="oc-retrieving-multiple-models"></a></p><h3 id="检索多个模型"><a href="#检索多个模型" class="header-anchor">#</a> 检索多个模型</h3><p>一旦你创建了一个模型和<a href="./../database/structure.html#oc-migration-structure">其关联的数据库表</a>，你就可以开始从你的数据库中检索数据了。将每个模型视为一个强大的 <a href="./../database/query.html">查询构建器</a>，允许您查询与模型关联的数据库表。例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flights</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">all</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="访问字段值"><a href="#访问字段值" class="header-anchor">#</a> 访问字段值</h4><p>如果您有模型实例，则可以通过访问相应的属性来访问模型的字段值。 例如，让我们遍历查询返回的每个 <code>Flight</code> 实例并回显 <code>name</code> 字段的值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="添加额外的约束"><a href="#添加额外的约束" class="header-anchor">#</a> 添加额外的约束</h4><p><code>all</code> 方法将返回模型表中的所有结果。 由于每个模型都充当 <a href="./../database/query.html">查询构建器</a>，因此您还可以为查询添加约束，然后使用 <code>get</code> 方法检索结果：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flights</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;desc&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">take</span><span class="token punctuation">(</span><span class="token number">10</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：由于模型是查询构建器，因此您应该熟悉 <a href="./../database/query.html">查询构建器</a> 上可用的所有方法。 您可以在模型查询中使用这些方法中的任何一种。</p></blockquote><h4 id="集合"><a href="#集合" class="header-anchor">#</a> 集合</h4><p>对于像 <code>all</code> 和 <code>get</code> 这样检索多个结果的方法，将返回一个 <code>Collection</code> 的实例。 此类提供 <a href="./../database/collection.html">各种有用的方法</a> 用于处理您的结果。 当然，你可以像数组一样简单地循环这个集合：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">echo</span> <span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="分块结果"><a href="#分块结果" class="header-anchor">#</a> 分块结果</h4><p>如果你需要处理数以千计的记录，请使用 <code>chunk</code> 命令。 <code>chunk</code> 方法将检索模型的&quot;分块&quot;，将它们提供给给定的 <code>Closure</code> 进行处理。 在处理大型结果集时，使用 <code>chunk</code> 方法将节省内存：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">chunk</span><span class="token punctuation">(</span><span class="token number">200</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$flights</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token variable">$flights</span> <span class="token keyword">as</span> <span class="token variable">$flight</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">//</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>传递给该方法的第一个参数是您希望每个&quot;分块&quot;接收的记录数。 作为第二个参数传递的闭包将为从数据库中检索到的每个块调用。</p><p><a id="oc-retrieving-a-single-model"></a></p><h3 id="检索单个模型"><a href="#检索单个模型" class="header-anchor">#</a> 检索单个模型</h3><p>传递到方法的第一个参数是希望每个&quot;分块&quot;接收的数据量。闭包作为第二个参数传递，它在每次从数据库中检索分块的时候调用。它将执行数据库查询把检索分块的结果传递给闭包方法。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 通过主键检索模型</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 检索与查询约束匹配的第一个模型</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">first</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="未找到-异常"><a href="#未找到-异常" class="header-anchor">#</a> &quot;未找到&quot;异常</h4><p>有时你希望在未找到模型时抛出异常。这在控制器和路由中非常有用。 <code>findOrFail</code> 和 <code>firstOrFail</code> 方法会检索查询的第一个结果，如果未找到，将抛出 <code>Illuminate\\Database\\Eloquent\\ModelNotFoundException</code> 异常：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">findOrFail</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$model</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;legs&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">firstOrFail</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在<a href="./../services/router.html">开发API</a>时，如果未捕获异常，则会自动将&#39;404&#39;HTTP响应发送回用户，因此在使用这些方法时，无需编写显式检查以返回&#39;404&#39;响应：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Route</span><span class="token operator">::</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;/api/flights/{id}&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">findOrFail</span><span class="token punctuation">(</span><span class="token variable">$id</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="检索集合"><a href="#检索集合" class="header-anchor">#</a> 检索集合</h3><p>您还可以使用查询生成器提供的 <code>count</code>、<code>sum</code>、<code>max</code> 和其他 <a href="./../database/query.html#oc-aggregates">聚合函数</a>。 这些方法返回适当的标量值而不是完整的模型实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$count</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">count</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$max</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">max</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="插入-更新模型"><a href="#插入-更新模型" class="header-anchor">#</a> 插入 &amp; 更新模型</h2><p>插入和更新数据是模型的基本功能，与传统的 SQL 语句相比，它使过程变得轻松。</p><h3 id="插入"><a href="#插入" class="header-anchor">#</a> 插入</h3><p>要在数据库中创建新记录，只需创建一个新模型实例，在模型上设置属性，然后调用 <code>save</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;悉尼飞往堪培拉&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>在这个例子中，我们只是创建了一个新的 <code>Flight</code> 模型实例并分配了 <code>name</code> 属性。 当我们调用 <code>save</code> 方法时，一条记录将被插入到数据库中。 <code>created_at</code> 和 <code>updated_at</code> 时间戳也会自动设置，因此无需手动设置。</p><h3 id="更新"><a href="#更新" class="header-anchor">#</a> 更新</h3><p><code>save</code> 方法也可以用来更新数据库中已经存在的模型。 要更新模型，您应该检索它，设置您希望更新的任何属性，然后调用 <code>save</code> 方法。 同样，<code>updated_at</code> 时间戳将自动更新，因此无需手动设置其值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token property">name</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;上海飞往北京&#39;</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>还可以针对与给定查询匹配的任意数量的模型执行更新。 在此示例中，所有&quot;活动&quot;且&quot;目的地&quot;为&quot;圣地亚哥&quot;的航班都将被标记为延误：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token constant boolean">true</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;destination&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Perth&#39;</span><span class="token punctuation">)</span>
    <span class="token operator">-&gt;</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;delayed&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>update</code> 方法需要一个表示应该更新的列的字段和值的数组。</p><p><a id="oc-mass-assignment"></a></p><h3 id="批量赋值"><a href="#批量赋值" class="header-anchor">#</a> 批量赋值</h3><p>你也可以使用 <code>create</code> 方法来保存新模型，此方法会返回模型实例。不过，在使用之前，您需要在模型上指定一个 <code>fillable</code> 或 <code>guarded</code> 属性，因为所有模型都默认不可进行批量赋值。注意 <code>fillable</code> 或 <code>guarded</code> 都不会影响后端表单的提交，只影响 <code>create</code> 或 <code>fill</code> 方法。</p><p>当用户通过 HTTP 请求传入一个意外的参数，并且该参数更改了数据库中你不需要更改的字段时。比如：恶意用户可能会通过 HTTP 请求传入 <code>is_admin</code> 参数，然后将其传给 <code>create</code> 方法，此操作能让用户将自己升级成管理员。</p><p>所以，在开始之前，你应该定义好模型上的哪些属性是可以被批量赋值的。你可以通过模型上的 <code>$fillable</code> 属性来实现。 例如：让 <code>Flight</code> 模型的 <code>name</code> 属性可以被批量赋值：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Flight</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 可批量分配的属性。
     *
     * @var array
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$fillable</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>一旦我们设置好了可以批量赋值的属性，就可以通过 <code>create</code> 方法插入新数据到数据库中了。 <code>create</code> 方法将返回保存的模型实例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">create</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>$fillable</code> 可以看作批量赋值的「白名单」, 你也可以使用 <code>$guarded</code> 属性来实现。 <code>$guarded</code> 属性包含的是不允许批量赋值的数组。也就是说， <code>$guarded</code> 从功能上将更像是一个「黑名单」。注意：你只能使用 <code>$fillable</code> 或 <code>$guarded</code> 二者中的一个，不可同时使用：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">Flight</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 不可批量分配的属性。
     *
     * @var array
     */</span>
    <span class="token keyword">protected</span> <span class="token variable">$guarded</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;price&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在上面的示例中，<strong>除 <code>price</code></strong> 之外的所有属性都可以批量赋值。</p><h4 id="其他创建方式"><a href="#其他创建方式" class="header-anchor">#</a> 其他创建方式</h4><p>有时您可能希望只实例化模型的新实例。你可以使用 <code>make</code> 方法来做到这一点。 <code>make</code> 方法将简单地返回一个新实例，而不保存或创建任何内容。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">make</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 功能与...相同</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">fill</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>这里有两个你可能用来批量赋值的方法： <code>firstOrCreate</code> 和 <code>firstOrNew</code>。<code>firstOrCreate</code> 方法会通过给定的 列 / 值 来匹配数据库中的数据。如果在数据库中找不到对应的模型， 则会从第一个参数的属性乃至第二个参数的属性中创建一条记录插入到数据库。</p><p><code>firstOrNew</code> 方法像 <code>firstOrCreate</code> 方法一样尝试通过给定的属性查找数据库中的记录。不同的是，如果 <code>firstOrNew</code> 方法找不到对应的模型，会返回一个新的模型实例。注意 <code>firstOrNew</code> 返回的模型实例尚未保存到数据库中，你需要手动调用 <code>save</code> 方法来保存：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// 通过属性检索航班，否则创建它</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">firstOrCreate</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 通过属性检索航班，或实例化一个新实例</span>
<span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">firstOrNew</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Flight 10&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="删除模型"><a href="#删除模型" class="header-anchor">#</a> 删除模型</h2><p>要删除模型，请在模型实例上调用 <code>delete</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">find</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="通过主键删除模型"><a href="#通过主键删除模型" class="header-anchor">#</a> 通过主键删除模型</h4><p>在上面的示例中，我们在调用<code>delete</code>方法之前从数据库中检索模型。 但是，如果您知道模型的主键，则可以不检索而直接删除模型。 为此，请调用 <code>destroy</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">destroy</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="通过查询删除模型"><a href="#通过查询删除模型" class="header-anchor">#</a> 通过查询删除模型</h4><p>您还可以对一组模型运行删除查询。 在此示例中，我们将删除所有标记为非活动的航班：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$deletedRows</span> <span class="token operator">=</span> <span class="token class-name static-context">Flight</span><span class="token operator">::</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;active&#39;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">delete</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：比较重要的一点是在直接从查询中删除记录时不会触发<a href="#oc-model-events">模型事件</a></p></blockquote><p><a id="oc-query-scopes"></a></p><h2 id="查询范围"><a href="#查询范围" class="header-anchor">#</a> 查询范围</h2><p>范围允许您定义可以在整个应用程序中轻松重用的通用约束集。 例如，您可能需要经常检索所有被认为&quot;受欢迎&quot;的用户。 要定义范围，只需在模型方法前面加上 <code>scope</code>：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 将查询范围限定为仅包括受欢迎的用户。
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopePopular</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;votes&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;&gt;&#39;</span><span class="token punctuation">,</span> <span class="token number">100</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token comment">/**
     * 将查询范围限定为仅包括活动用户。
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeActive</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;is_active&#39;</span><span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><h4 id="使用查询范围"><a href="#使用查询范围" class="header-anchor">#</a> 使用查询范围</h4><p>一旦定义了范围，您就可以在查询模型时调用范围方法。不过，在调用这些方法时不必包含 <code>scope</code> 前缀。甚至可以链式调用多个范围，例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">popular</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">active</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">orderBy</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;created_at&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="动态范围"><a href="#动态范围" class="header-anchor">#</a> 动态范围</h4><p>有时您可能希望定义一个接受参数的范围。 要开始，只需将您的附加参数添加到您的范围。 范围参数应该在 <code>$query</code> 参数之后定义：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">class</span> <span class="token class-name-definition class-name">User</span> <span class="token keyword">extends</span> <span class="token class-name">Model</span>
<span class="token punctuation">{</span>
    <span class="token comment">/**
     * 将查询范围限定为仅包括给定类型的用户。
     */</span>
    <span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">scopeApplyType</span><span class="token punctuation">(</span><span class="token variable">$query</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token variable">$query</span><span class="token operator">-&gt;</span><span class="token function">where</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;type&#39;</span><span class="token punctuation">,</span> <span class="token variable">$type</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>现在您可以在调用范围时传递参数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$users</span> <span class="token operator">=</span> <span class="token class-name static-context">User</span><span class="token operator">::</span><span class="token function">applyType</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">get</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><a id="oc-model-events"></a></p><h2 id="事件"><a href="#事件" class="header-anchor">#</a> 事件</h2><p>模型会触发几个事件，允许您连接到模型生命周期中的各个点。 每次在数据库中保存或更新特定模型类时，事件允许您轻松执行代码。 事件是通过覆盖类中的特殊方法来定义的，可以使用以下方法覆盖：</p><div class="table"><table tabindex="0"><thead><tr><th>事件</th><th>描述</th></tr></thead><tbody><tr><td><strong>beforeCreate</strong></td><td>在模型保存之前，首次创建时。</td></tr><tr><td><strong>afterCreate</strong></td><td>模型保存后，首次创建时。</td></tr><tr><td><strong>beforeSave</strong></td><td>在保存模型之前，创建或更新模型。</td></tr><tr><td><strong>afterSave</strong></td><td>保存模型后，创建或更新模型。</td></tr><tr><td><strong>beforeValidate</strong></td><td>在验证提供的模型数据之前。</td></tr><tr><td><strong>afterValidate</strong></td><td>提供的模型数据经过验证后。</td></tr><tr><td><strong>beforeUpdate</strong></td><td>在保存现有模型之前。</td></tr><tr><td><strong>afterUpdate</strong></td><td>保存现有模型后。</td></tr><tr><td><strong>beforeDelete</strong></td><td>在删除现有模型之前。</td></tr><tr><td><strong>afterDelete</strong></td><td>删除现有模型后。</td></tr><tr><td><strong>beforeRestore</strong></td><td>在恢复软删除的模型之前。</td></tr><tr><td><strong>afterRestore</strong></td><td>恢复软删除的模型后。</td></tr><tr><td><strong>beforeFetch</strong></td><td>在填充现有模型之前。</td></tr><tr><td><strong>afterFetch</strong></td><td>在填充现有模型之后。</td></tr></tbody></table></div><p>使用事件的示例：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * 为这个模型生成一个 URL slug
 */</span>
<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><blockquote><p><strong>注意</strong>：使用 <a href="./relations.html#oc-deferred-binding">延迟绑定</a> 创建的关系(即：文件附件)如果尚未提交，则在 <code>afterSave</code> 模型事件中将不可用。 要访问未提交的绑定，请在关系上使用 <code>withDeferred($sessionKey)</code> 方法。 示例：<code>$this-&gt;images()-&gt;withDeferred(post(&#39;_session_key&#39;))-&gt;get();</code></p></blockquote><h3 id="基本用法"><a href="#基本用法" class="header-anchor">#</a> 基本用法</h3><p>每当第一次保存新模型时，<code>beforeCreate</code> 和 <code>afterCreate</code> 事件都会触发。 如果一个模型已经存在于数据库中并且调用了 <code>save</code> 方法，<code>beforeUpdate</code> / <code>afterUpdate</code> 事件将被触发。 但是，在这两种情况下，<code>beforeSave</code> / <code>afterSave</code> 事件都会触发。</p><p>例如，让我们定义一个事件侦听器，在第一次创建模型时填充 slug 属性：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * 为这个模型生成一个 URL slug
 */</span>
<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>从事件中返回 <code>false</code> 将取消 <code>save</code> / <code>update</code> 操作：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">beforeCreate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token variable">$user</span><span class="token operator">-&gt;</span><span class="token function">isValid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token constant boolean">false</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>可以使用 <code>original</code> 属性访问旧值。 例如：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">afterUpdate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">title</span> <span class="token operator">!=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">original</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;title&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 标题已更改</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre></div><p>您可以使用 <code>bindEvent</code> 方法从外部绑定到模型的单个实例的 <a href="./../services/events.html">本地事件</a>。 事件名称应与方法覆盖名称相同，前缀为<code>model.</code>。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$flight</span> <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">Flight</span><span class="token punctuation">;</span>
<span class="token variable">$flight</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeCreate&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">slug</span> <span class="token operator">=</span> <span class="token class-name static-context">Str</span><span class="token operator">::</span><span class="token function">slug</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">name</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h2 id="扩展模型"><a href="#扩展模型" class="header-anchor">#</a> 扩展模型</h2><p>由于模型 <a href="./../services/behaviors.html">配备使用行为</a>，它们可以使用静态的 <code>extend</code> 方法进行扩展。 该方法接受一个闭包并将模型对象传递给它。</p><p>在闭包内，您可以向模型添加关系。 在这里，我们扩展了 <code>Backend\\Models\\User</code> 模型，以包含引用 <code>Acme\\Demo\\Models\\Profile</code> 模型的配置文件(有一个)关系。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token property">hasOne</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;profile&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;Acme\\Demo\\Models\\Profile&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;key&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;user_id&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>这种方法也可以用来绑定到 <a href="#oc-model-events">本地事件</a>，下面的代码监听 <code>model.beforeSave</code> 事件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;model.beforeSave&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">use</span> <span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// ...</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>此外，还有一些方法可以扩展受保护的模型属性。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context"><span class="token punctuation">\\</span>Backend<span class="token punctuation">\\</span>Models<span class="token punctuation">\\</span>User</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$model</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// 添加演员属性</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addCasts</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;some_extended_field&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;int&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// 添加日期属性</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addDateAttribute</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;updated_at&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">// 添加可填充或 jsonable 字段</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addFillable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;first_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$model</span><span class="token operator">-&gt;</span><span class="token function">addJsonable</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;some_data&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>注意</strong>：通常放置代码的最佳位置是在插件注册类的<code>boot</code>方法中，因为这将在每个请求上运行，确保您对模型所做的扩展随处可用。</p></blockquote>`,135))])}const y=c(u,[["render",k]]);export{b as __pageData,y as default};
